{
  "name": "Elveflow MUX 1/12 微流控分配阀",
  "name_en": "Elveflow MUX 1/12 Microfluidic Distributor Valve",
  "manufacturer": "Elveflow",
  "description": "这是一台用于微流控与液路切换的 1 进 12 出分配阀/多路选择器，可将单一路流体依次切换到多个通道或样品路径。它常用于微流控实验、自动化注液、试剂分配、样品切换和多通道流路管理。",
  "description_en": "This is a 1-to-12 microfluidic distributor/selector valve used to route a single fluid line to multiple channels or sample paths. It is commonly used in microfluidics experiments, automated reagent delivery, sample switching, and multi-line fluid path management.",
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开与分配阀的连接。",
      "description_en": "Open the connection to the distributor valve."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与分配阀的连接。",
      "description_en": "Close the connection to the distributor valve."
    },
    {
      "action_name": "auto-home",
      "description": "使阀门回零并回到起始通道位置。",
      "description_en": "Home the valve and return it to the starting channel position."
    },
    {
      "action_name": "auto-set_valve",
      "description": "设置阀门当前通道位置。",
      "description_en": "Set the current valve channel position."
    },
    {
      "action_name": "auto-wait_for_valve_movement",
      "description": "等待阀门移动完成。",
      "description_en": "Wait for the valve movement to complete."
    },
    {
      "action_name": "auto-loadDLL",
      "description": "加载与设备通信所需的控制库。",
      "description_en": "Load the control library required to communicate with the device."
    },
    {
      "action_name": "auto-get_valve",
      "description": "获取阀门当前通道位置。",
      "description_en": "Get the current valve channel position."
    }
  ],
  "tag_hints": [
    "microfluidics",
    "selector valve",
    "fluid routing",
    "1-to-12 distribution",
    "sample switching",
    "reagent delivery",
    "multi-channel fluidics"
  ]
}

